import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, putJson } from '../../api/http';
import { useCurrentUser } from '../session/SignIn';

// The sheet's rate for each grade: a percent with two decimals, set here. A grade without a rate
// shows n/a, and so does anything due that depends on it. Money and percents come from the server as
// strings with two decimals and are worked in whole cents and hundredths of a percent, never floats.
export type Rate = { grade: string; pct: string };

const GRADES = ['A', 'B', 'C'];
export const NA = 'n/a';

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'];
const ratesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;

export function useRates(sheet: string): Rate[] {
  return (
    useQuery({
      queryKey: ratesKey(sheet),
      queryFn: () => getJson<Rate[]>(ratesPath(sheet)),
      enabled: !!sheet,
    }).data ?? []
  );
}

/** The grade's percent, or undefined when the grade has no rate. */
export function rateOf(rates: Rate[], grade: string): string | undefined {
  return rates.find((r) => r.grade === grade)?.pct;
}

/** A two-decimal string as a whole number of hundredths. */
export const toHundredths = (value: string): bigint => {
  const [whole, frac = ''] = value.split('.');
  return BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0') || '0');
};

/** Hundredths as a two-decimal string. */
export const fromHundredths = (h: bigint): string =>
  `${h / 100n}.${String(h % 100n).padStart(2, '0')}`;

/** amount × pct / 100, rounded half up to two decimals; n/a without a rate. Amounts are never negative. */
export function due(amount: string, pct: string | undefined): string {
  if (pct === undefined) return NA;
  // cents × hundredths-of-a-percent gives cents × 10000.
  return fromHundredths((toHundredths(amount) * toHundredths(pct) + 5000n) / 10000n);
}

/** Two-decimal values added up, skipping n/a. */
export function total(values: string[]): string {
  return fromHundredths(values.filter((v) => v !== NA).reduce((sum, v) => sum + toHundredths(v), 0n));
}

export function Rates({ sheet }: { sheet: string }) {
  const rates = useRates(sheet);
  return (
    <section>
      <h2>Rates</h2>
      <RateForm sheet={sheet} />
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const pct = rateOf(rates, g);
            return (
              <tr key={g} data-testid={pct === undefined ? undefined : `rate-row-${g}-start`}>
                <td>{g}</td>
                <td>
                  <span data-testid={`rate-current-${g}`}>
                    {pct === undefined ? NA : <span data-testid="rate-pct">{pct}</span>}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </section>
  );
}

function RateForm({ sheet }: { sheet: string }) {
  const queryClient = useQueryClient();
  const [grade, setGrade] = useState('A');
  const [pct, setPct] = useState('');
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const save = useMutation({
    mutationFn: (body: { grade: string; pct: string }) =>
      putJson<Rate>(`${ratesPath(sheet)}/${encodeURIComponent(body.grade)}${by}`, { pct: body.pct }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheet) });
      setPct('');
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        save.reset();
        // A missing, out-of-range or over-precise percent is refused by the server (400).
        save.mutate({ grade, pct });
      }}
    >
      <label>
        Grade{' '}
        <select
          data-testid="rate-form-grade"
          value={grade}
          onChange={(e) => {
            save.reset();
            setGrade(e.target.value);
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        Rate %{' '}
        <input
          data-testid="rate-form-pct"
          inputMode="decimal"
          value={pct}
          onChange={(e) => {
            save.reset();
            setPct(e.target.value);
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
        Set rate
      </button>
      {save.isError && (
        <span role="alert" data-testid="rate-form-error">
          {' '}
          {(save.error instanceof HttpError && save.error.status === 400 && save.error.reason)
            || 'The rate could not be saved.'}
        </span>
      )}
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import { useCurrentUser } from '../session/SignIn';
import { useSheetToday } from '../sheet/SheetToday';
import { due } from '../rates/Rates';

// A person's claims, listed under their row newest first. One form per row adds a claim, or edits
// the claim whose editor is open (URL state `editClaim`, the claim's id). Amounts come from the
// server as strings with two decimals and are added up in whole cents, never as floats. A claim's
// status moves DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID; the server refuses any other change.
// Opening gives a claim the sheet's next number, which voiding clears; a draft has none.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when the claim is opened; null for a draft or a voided claim. */
  number: number | null };

const ACTIONS = [
  { action: 'open', label: 'Open' },
  { action: 'settle', label: 'Settle' },
  { action: 'void', label: 'Void' },
];

type ClaimBody = { amount: string; date: string; note: string };

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'];
const sheetPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;

export function useClaims(sheet: string): Claim[] {
  return (
    useQuery({
      queryKey: claimsKey(sheet),
      queryFn: () => getJson<Claim[]>(`${sheetPath(sheet)}/claims`),
      enabled: !!sheet,
    }).data ?? []
  );
}

const toCents = (amount: string) => {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
};

/** Only OPEN and SETTLED claims count toward claimed, due-total and every total. */
const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** The counted claims' amounts added up, with two decimals. */
export function claimed(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + toCents(c.amount), 0);
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

export function ClaimedTotal({ sheet }: { sheet: string }) {
  const claims = useClaims(sheet);
  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims)}</strong>
    </p>
  );
}

/** The claims cell of a person's row: the claim form and the person's claims, newest first, each
 *  with its due at the person's grade's rate (`pct`, undefined when the grade has none). */
export function PersonClaims({ sheet, personId, claims, pct }: {
  sheet: string; personId: number; claims: Claim[]; pct: string | undefined;
}) {
  const [editId, setEditId] = useSearchParam('editClaim', asNumber);
  const editing = claims.find((c) => c.id === editId);

  return (
    <>
      {/* Keyed so opening another claim's editor (or closing it) refills the form. */}
      <ClaimForm key={editing ? `edit-${editing.id}` : 'add'} sheet={sheet} personId={personId}
        editing={editing} onDone={() => setEditId(undefined)} />
      <ul>
        {claims.map((c) => (
          <ClaimRow key={c.id} sheet={sheet} claim={c} pct={pct} onEdit={() => setEditId(c.id)} />
        ))}
      </ul>
    </>
  );
}

/** One claim: its fields, status and due, with its edit and status buttons. A refused status change
 *  shows the row's error, which the row's next action clears. */
function ClaimRow({ sheet, claim: c, pct, onEdit }: {
  sheet: string; claim: Claim; pct: string | undefined; onEdit: () => void;
}) {
  const queryClient = useQueryClient();
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const change = useMutation({
    mutationFn: (action: string) => postJson<Claim>(`${sheetPath(sheet)}/claims/${c.id}/${action}${by}`, {}),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });

  return (
    <li data-testid={`claim-row-${c.id}`}>
      #<span data-testid="claim-number">{c.number ?? ''}</span>{' '}
      <span data-testid="claim-amount">{c.amount}</span>{' '}
      <span data-testid="claim-date">{c.date}</span>{' '}
      <span data-testid="claim-note">{c.note}</span>{' '}
      <span data-testid="claim-status">{c.status}</span>{' '}
      Due <span data-testid="claim-due">{due(c.amount, pct)}</span>{' '}
      <button type="button" data-testid="claim-edit" onClick={() => { change.reset(); onEdit(); }}>
        Edit
      </button>
      {ACTIONS.map(({ action, label }) => (
        <button key={action} type="button" data-testid={`claim-${action}`} disabled={change.isPending}
          onClick={() => { change.reset(); change.mutate(action); }}>
          {label}
        </button>
      ))}
      {change.isError && (
        <span role="alert" data-testid="claim-error">
          {' '}
          {(change.error instanceof HttpError && change.error.reason) || 'The claim could not be changed.'}
        </span>
      )}
    </li>
  );
}

function ClaimForm({ sheet, personId, editing, onDone }: {
  sheet: string; personId: number; editing?: Claim; onDone: () => void;
}) {
  const queryClient = useQueryClient();
  const today = useSheetToday(sheet);
  const [amount, setAmount] = useState(editing?.amount ?? '');
  // Undefined until changed: the sheet's today, which the server fills in when the date is blank.
  const [date, setDate] = useState<string | undefined>(editing?.date);
  const [note, setNote] = useState(editing?.note ?? '');
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const save = useMutation({
    mutationFn: (body: ClaimBody) =>
      editing
        ? putJson<Claim>(`${sheetPath(sheet)}/claims/${editing.id}${by}`, body)
